const $=id=>document.getElementById(id);
let rows=[],index=0,playing=false,timer=null,ctx,master,voices=new Set();
const controls=['instrument','scale','pitch','duration','speed','volume'];
const defaults={instrument:'piano',scale:'continuous',pitch:'12',duration:'45',speed:'1',volume:'30'};
function saved(){try{return JSON.parse(localStorage.getItem('earthtone-settings')||'null')}catch{return null}}
function persist(){try{localStorage.setItem('earthtone-settings',JSON.stringify(Object.fromEntries(controls.map(k=>[k,$(k).value]))))}catch{}}
function pitchFor(value,settings){let n=value*Number(settings?.pitch??$('pitch').value);const scales={major:[0,2,4,5,7,9,11],minor:[0,2,3,5,7,8,10],pentatonic:[0,2,4,7,9]};const scale=scales[settings?.scale??$('scale').value];if(scale){let candidates=[];for(let oct=-5;oct<6;oct++)scale.forEach(s=>candidates.push(oct*12+s));n=candidates.reduce((a,b)=>Math.abs(b-n)<Math.abs(a-n)?b:a)}return 220*2**(n/12)}
function interval(){return Number($('duration').value)/rows.length/Number($('speed').value)}
async function audio(){if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();master=ctx.createGain();master.connect(ctx.destination)}await ctx.resume();master.gain.setTargetAtTime(Number($('volume').value)/100,ctx.currentTime,.03)}
function silence(){voices.forEach(o=>{try{o.stop()}catch{}});voices.clear()}
const instruments={
 piano:{partials:[[1,1],[2,.45],[3,.2],[4,.09]],attack:.008,decay:true},
 strings:{partials:[[1,1],[2,.34],[3,.17],[4,.08]],attack:.08,decay:false},
 bell:{partials:[[1,1],[2.76,.35],[5.4,.12]],attack:.006,decay:true},
 triangle:{partials:[[1,1],[2.32,.4],[4.25,.16]],attack:.003,decay:true},
 harp:{partials:[[1,1],[2,.28],[3,.12]],attack:.012,decay:true}
};
function note(freq,seconds,type=$('instrument').value){const now=ctx.currentTime,preset=instruments[type]||instruments.piano;const sum=preset.partials.reduce((n,p)=>n+p[1],0);for(const [multiple,amp]of preset.partials){const osc=ctx.createOscillator(),env=ctx.createGain();osc.type='sine';osc.frequency.value=freq*multiple;const peak=.4*amp/sum,attack=Math.min(preset.attack,seconds*.2);env.gain.setValueAtTime(.0001,now);env.gain.linearRampToValueAtTime(peak,now+attack);if(!preset.decay)env.gain.setValueAtTime(peak*.8,now+seconds*.65);env.gain.exponentialRampToValueAtTime(.0001,now+seconds*.95);osc.connect(env);env.connect(master);osc.start(now);osc.stop(now+seconds);voices.add(osc);osc.onended=()=>{voices.delete(osc);osc.disconnect();env.disconnect()}}}
let previewTimers=[],previewToken=0;
function stopPreview(){previewToken++;previewTimers.forEach(clearTimeout);previewTimers=[];silence();document.querySelectorAll('[data-preview]').forEach(b=>{b.textContent='▶ Hear sample';b.setAttribute('aria-pressed','false')})}
async function previewChoice(choice,button){stopPreview();const token=previewToken;try{await audio();if(token!==previewToken)return;const settings={...Object.fromEntries(controls.map(k=>[k,$(k).value])),...answers,...choice};const gap=Number(settings.duration)/146/Number(settings.speed);const values=[-.2,0,.3,.65,1.05,1.28];button.textContent='■ Stop sample';button.setAttribute('aria-pressed','true');$('sampleStatus').textContent='Playing a short example. Previewing does not select an answer.';values.forEach((value,i)=>previewTimers.push(setTimeout(()=>{if(token===previewToken)note(pitchFor(value,settings),gap*.95,settings.instrument)},i*gap*1000)));previewTimers.push(setTimeout(()=>{if(token===previewToken){stopPreview();$('sampleStatus').textContent='Sample finished. Choose an answer or compare another.'}},values.length*gap*1000))}catch{$('sampleStatus').textContent='Audio could not start. You can still choose an answer.'}}
function fmt(seconds){return `${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`}
function draw(){if(!rows.length)return;const svg=$('chart');const min=Math.min(-.5,...rows.map(r=>r.value)),max=Math.max(1.5,...rows.map(r=>r.value));const x=i=>45+i/(rows.length-1)*730,y=v=>220-(v-min)/(max-min)*195;const points=rows.map((r,i)=>`${x(i)},${y(r.value)}`).join(' ');let html='<defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ce542e" stop-opacity=".18"/><stop offset="1" stop-color="#ce542e" stop-opacity="0"/></linearGradient></defs>';for(let v=-.5;v<=max;v+=.5){html+=`<line x1="45" x2="775" y1="${y(v)}" y2="${y(v)}" stroke="${v===0?'#849685':'#dce1d5'}" stroke-dasharray="${v===0?'4 4':'0'}"/><text x="0" y="${y(v)+4}" fill="#71816f" font-size="11">${v>0?'+':''}${v.toFixed(1)}°</text>`}html+=`<polygon points="45,220 ${points} 775,220" fill="url(#fill)"/><polyline points="${points}" fill="none" stroke="#ce542e" stroke-width="2.5" stroke-linejoin="round"/>`;for(let i=0;i<rows.length;i++){if(i===0||i===rows.length-1||(rows[i].year%20===0&&i<rows.length-8))html+=`<text x="${x(i)}" y="248" text-anchor="middle" fill="#71816f" font-size="11">${rows[i].year}</text>`}html+=`<line x1="${x(index)}" x2="${x(index)}" y1="15" y2="225" stroke="#213e35" opacity=".35"/><circle cx="${x(index)}" cy="${y(rows[index].value)}" r="6" fill="#213e35" stroke="#fafbf5" stroke-width="3"/>`;svg.innerHTML=html}
function render(announce=false){if(!rows.length)return;let r=rows[index];$('year').textContent=r.year;$('anomaly').textContent=(r.value>=0?'+':'')+r.value.toFixed(2);$('frequency').textContent=Math.round(pitchFor(r.value));$('scrub').value=index;let total=Number($('duration').value)/Number($('speed').value);$('progress').textContent=`${fmt(index/rows.length*total)} / ${fmt(total)}`;if(announce)$('caption').textContent=`${r.year}: ${Math.abs(r.value).toFixed(2)}°C ${r.value>=0?'warmer':'cooler'} than the 1951–1980 baseline. ${Math.round(pitchFor(r.value))} Hz.`;draw()}
function pause(){playing=false;clearTimeout(timer);stopPreview();$('play').textContent='▶ Listen to Earth';$('status').textContent='Ready to listen'}
function tick(){if(!playing)return;render(index%10===0);note(pitchFor(rows[index].value),interval());timer=setTimeout(()=>{if(index>=rows.length-1){pause();render(true);$('status').textContent='Journey complete';return}index++;tick()},interval()*1000)}
$('play').onclick=async()=>{if(playing){pause();return}try{await audio();if(index===rows.length-1)index=0;playing=true;$('play').textContent='Ⅱ Pause';$('status').textContent='● Playing live';tick()}catch{$('caption').textContent='Audio is unavailable in this browser. You can still explore every measurement with the timeline.'}};
$('reset').onclick=()=>{pause();index=0;render(true)};$('scrub').oninput=()=>{pause();index=Number($('scrub').value);render(true)};
$('baseline').onclick=async()=>{pause();try{await audio();note(220,.7);$('caption').textContent='Reference tone: 220 Hz represents a 0°C anomaly.'}catch{$('caption').textContent='Audio unavailable in this browser.'}};
function labels(){$('speedOut').textContent=$('speed').value+'×';$('volumeOut').textContent=$('volume').value+'%'}
controls.forEach(k=>{$(k).oninput=()=>{labels();persist();if(k==='volume'&&master)master.gain.setTargetAtTime(Number($('volume').value)/100,ctx.currentTime,.03);else if(playing)pause();render(true)}});
function applySettings(s){s={...s,instrument:({sine:'piano',pluck:'harp'}[s.instrument]||s.instrument||'piano')};controls.forEach(k=>{if(s[k]!==undefined)$(k).value=s[k]});labels();persist();render(true)}
applySettings(saved()||defaults);
const modal=$('modal');function show(html){pause();$('modalContent').innerHTML=html;if(!modal.open)modal.showModal()}
$('closeModal').onclick=()=>modal.close();
const tour=[['Welcome to Earthtone','Listen to real global temperature measurements. Higher notes mean warmer years. Press play to start sound; nothing plays automatically.'],['Follow the warming score','The graph, year, temperature, and sound move together. Drag the timeline to inspect any year. Use rewind to start again.'],['Make the sound your own','Choose an instrument, musical scale, pitch increment, speed, duration, and loudness. The exact measurements remain unchanged. Major and minor modes round notes to a musical scale.'],['Explore with confidence','Use the 220 Hz baseline tone as a reference. Read or download the data below the player. Take the four-question listening quiz any time. All controls work with a keyboard.']];let tourIndex=0;
function showTour(){show(`<span class="eyebrow">QUICK TOUR · ${tourIndex+1} / ${tour.length}</span><h2>${tour[tourIndex][0]}</h2><p>${tour[tourIndex][1]}</p><div class="steps"><button id="skip">Skip tour</button><button class="primary" id="next">${tourIndex===3?'Start exploring':'Next →'}</button></div>`);$('skip').onclick=()=>modal.close();$('next').onclick=()=>{if(tourIndex===3)modal.close();else{tourIndex++;showTour()}}}
$('tourBtn').onclick=()=>{tourIndex=0;showTour()};modal.addEventListener('close',()=>{stopPreview();try{localStorage.setItem('earthtone-visited','yes')}catch{}});
const quiz=[{q:'Which sound feels most like you?',options:[['Piano','Clear & warm',{instrument:'piano'}],['Strings','Smooth & sustained',{instrument:'strings'}],['Bells','Bright & sparkling',{instrument:'bell'}],['Harp','Gentle & plucked',{instrument:'harp'}]]},{q:'What mood should your melody have?',options:[['Curious','Exact, continuous pitch',{scale:'continuous'}],['Hopeful','A major scale',{scale:'major'}],['Reflective','A minor scale',{scale:'minor'}],['Open & spacious','A pentatonic scale',{scale:'pentatonic'}]]},{q:'How much time do you have?',options:[['A quick glimpse','30-second journey',{duration:'30',speed:'1'}],['A little escape','45-second journey',{duration:'45',speed:'1'}],['Room to explore','60-second journey',{duration:'60',speed:'1'}],['Time to reflect','90-second journey',{duration:'90',speed:'1'}]]},{q:'How strongly should the pitch change?',options:[['Subtle','6 semitones per °C',{pitch:'6'}],['Balanced','12 semitones per °C',{pitch:'12'}],['Expressive','18 semitones per °C',{pitch:'18'}],['Dramatic','24 semitones per °C',{pitch:'24'}]]}];let qi=0,answers={};function showQuiz(){const q=quiz[qi];show(`<span class="eyebrow">FIND YOUR SOUND · ${qi+1} / 4</span><h2>${q.q}</h2><p>Listen before you choose. Samples are synthesized instrument previews, not recordings.</p><p id="sampleStatus" aria-live="polite">${qi===2?'Short excerpts demonstrate the pacing of each duration.':'Each sample uses the same illustrative rising values for a fair comparison.'}</p><div class="choices">${q.options.map((o,i)=>`<div class="choiceCard"><button data-choice="${i}" aria-label="Choose ${o[0]}">${o[0]}<small>${o[1]}</small></button><button class="sampleBtn" data-preview="${i}" aria-label="Preview ${o[0]}" aria-pressed="false">▶ Hear sample</button></div>`).join('')}</div>`);document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{if(b.getAttribute('aria-pressed')==='true'){stopPreview();$('sampleStatus').textContent='Sample stopped.'}else previewChoice(q.options[Number(b.dataset.preview)][2],b)});document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{Object.assign(answers,q.options[Number(b.dataset.choice)][2]);qi++;if(qi<4)showQuiz();else{applySettings(answers);show('<span class="eyebrow">YOUR EARTH, YOUR SOUND</span><h2>Your listening style is ready.</h2><p>Your choices are applied to the studio. Adjust speed and loudness there whenever you like. Your preferences stay in this browser.</p><button class="primary" id="finishQuiz">Explore my jukebox →</button>');$('finishQuiz').onclick=()=>modal.close()}})}$('quizBtn').onclick=()=>{qi=0;answers={};showQuiz()};
$('tableBtn').onclick=()=>show(`<span class="eyebrow">NASA GISTEMP v4 · ANNUAL MEANS</span><h2>The measurements</h2><p>Temperature anomalies in °C relative to 1951–1980. Only complete years are included in playback.</p><table><thead><tr><th>Year</th><th>Anomaly (°C)</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.year}</td><td>${r.value.toFixed(2)}</td></tr>`).join('')}</tbody></table>`);
$('clearPrefs').onclick=()=>{pause();applySettings(defaults);$('caption').textContent='Default listening settings restored.'};
async function load(){try{const res=await fetch('gistemp.csv');if(!res.ok)throw Error();const text=await res.text();rows=text.trim().split(/\r?\n/).filter(l=>/^\d{4},/.test(l)).map(l=>{let c=l.split(',');return{year:Number(c[0]),value:Number(c[13]),complete:c.slice(1,13).every(v=>v.trim()!==''&&Number.isFinite(Number(v)))}}).filter(r=>r.complete&&Number.isFinite(r.value));if(!rows.length)throw Error();$('scrub').max=rows.length-1;$('play').disabled=false;$('status').textContent='Ready to listen';$('sourceDetail').textContent=`NASA GISTEMP v4 · ${rows[0].year}–${rows.at(-1).year} · ${rows.length} complete annual means. Downloaded November 14, 2026. Values relative to 1951–1980; later NASA revisions may change this snapshot.`;render();try{if(!localStorage.getItem('earthtone-visited'))showTour()}catch{showTour()}}catch{$('status').textContent='Data unavailable';$('caption').textContent='Could not load the temperature CSV. Reload to try again. No synthetic data is substituted.'}}
load();
